    /*
     * Function to read and parse the  Rules
     * rule: B23/S36
     */

    void parseBornSurvive(String rule) {
        int Smode = 1;
        int Bmode = 2;
        int noMode = 0;
        int currentMode = noMode;
        for (int i = 0; i < rule.length(); i++) {
            char curChar = rule.charAt(i);
            if (curChar == 'S' || curChar == 's') {
                currentMode = Smode;
            } else if (curChar == 'B' || curChar == 'b') {
                currentMode = Bmode;
            } else {
                if (currentMode == Smode) {
                    switch (curChar) {
                        case '0':
                            Survive[0] = 1;
                            break;
                        case '1':
                            Survive[1] = 1;
                            break;
                        case '2':
                            Survive[2] = 1;
                            break;
                        case '3':
                            Survive[3] = 1;
                            break;
                        case '4':
                            Survive[4] = 1;
                            break;
                        case '5':
                            Survive[5] = 1;
                            break;
                        case '6':
                            Survive[6] = 1;
                            break;
                        case '7':
                            Survive[7] = 1;
                            break;
                        case '8':
                            Survive[8] = 1;
                            break;
                        default:
                            break;
                    }
                } else if (currentMode == Bmode) {
                    switch (curChar) {
                        case '0':
                            Born[0] = 1;
                            break;
                        case '1':
                            Born[1] = 1;
                            break;
                        case '2':
                            Born[2] = 1;
                            break;
                        case '3':
                            Born[3] = 1;
                            break;
                        case '4':
                            Born[4] = 1;
                            break;
                        case '5':
                            Born[5] = 1;
                            break;
                        case '6':
                            Born[6] = 1;
                            break;
                        case '7':
                            Born[7] = 1;
                            break;
                        case '8':
                            Born[8] = 1;
                            break;
                        default:
                            break;
                    }
                }
            }
        }
    }

    /*
     * Hipertoroidal LifeLikeCA, where all edges from LifeLikeCA are connected
     */
    int toroidalNeighbor(int x, int y) {
        int sum = 0;
        for (int i = 0; i < 8; i++) { //i < 8
            int curX = (x + ROW + xdirections[i]) % ROW;
            int curY = (y + COL + ydirections[i]) % COL;
            //System.out.println("x: " + curX + "  y: " + curY);
            sum += prevMatrix[curX][curY];
        }
        return sum;
    }
    /*
     * Traditionally LifeLikeCA, where the edges are not take in count
     */

    int TraditionalNeighbor(int x, int y, int border) {
        int sum = 0;
        for (int i = 0; i < 8; i++) {
            int curX = x + xdirections[i];
            int curY = y + ydirections[i];
            if (curX < ROW && curX >= 0 && curY < COL && curY >= 0) {
                sum += prevMatrix[curX][curY];
            } else {
                sum += border;
            }
        }
        return sum;
    }

    public int valueAt(int x, int y) {
        return curMatrix[x][y];
    }
    /*/
     * Number of iterations: Time step to evolve LifeLikeCA
     */

    public void step(int days) {
//      executes the continuation of the program
        for (int g = 0; g < days; g++) {
            // printBoard();
            // repaint(); // use in JPanel mode
            runStep();
            copyBoard(prevMatrix, curMatrix);
            //repaint();
        }

    }
    // Runs one iteration

    private void runStep() {
        for (int x = 0; x < ROW; x++) {
            for (int y = 0; y < COL; y++) {
                int theSum;
                if (useToroidalGrid) {//Toroidal mode
                    theSum = toroidalNeighbor(x, y);
                } else {
                    theSum = TraditionalNeighbor(x, y, defaultConstantBorder);
                }
                if (prevMatrix[x][y] == 1) { //==1
                    if (Survive[theSum] > 0) {//1
                        curMatrix[x][y] = 1;
                    } else {
                        curMatrix[x][y] = 0;
                    }
                } else {
                    if (Born[theSum] > 0) {
                        curMatrix[x][y] = 1;
                    } else {
                        curMatrix[x][y] = 0;
                    }
                }
            }
        }
        tempo+=1;
    }

    public void clear() {
        for (int k = 0; k < ROW; k++) {
            for (int m = 0; m < COL; m++) {
                curMatrix[k][m] = 0;
                prevMatrix[k][m]=0;
            }
        }
        tempo=0;
    }
    public int getIterations()
    {
        return tempo;
    }

    public void random() {
        clear();
        Random randGen = new Random(1);
        double random = 0;
        // Initial State:
        for (int i = 0; i < ROW; i++) {
            for (int j = 0; j < COL; j++) {
                random = randGen.nextDouble();
                if (random < initialProbability) {
                    curMatrix[i][j] = 1;
                    prevMatrix[i][j] = 1;
                } else {
                    curMatrix[i][j] = 0;
                    prevMatrix[i][j] = 0;
                }
            }
        }
        repaint();
    }

    public void replica(int f, int c) {
        curMatrix[f][c] = (curMatrix[f][c] == 1 ? 0 : 1);
        prevMatrix[f][c] = curMatrix[f][c];
    }

    public void homogeneo() {
        clear();
        // Initial State:
        for (int i = 0; i < ROW / 2; i++) {
            for (int j = 0; j < COL; j++) {
                curMatrix[i][j] = 1;
                prevMatrix[i][j] = 1;
            }
        }
        for (int i = ROW / 2; i < ROW; i++) {
            for (int j = 0; j < COL; j++) {
                curMatrix[i][j] = 0;
                prevMatrix[i][j] = 0;
            }
        }
        repaint();
    }
    
