    public double countAlive() {
        int contador = 0;
        for (int k = 0; k < ROW; k++) {
            for (int m = 0; m < COL; m++) {
                if (curMatrix[k][m] == 1) {
                    contador++;
                }
            }
        }
        return contador;
    }

    public double percentageAlive() {
        double contador = countAlive();
        return (contador * 100) / (ROW * COL);
    }

    public double entropy() {
        double B = countAlive();
        double N = (ROW * COL) - B;
        double blancos = B / (ROW * COL);
        double negros = 1 - blancos;
        double H = (-1) * ((B * log2(blancos)) + (N * log2(negros)));
        H = H / (ROW * COL); // Normalize
        return H;
    }

    public double log2(double x) {
        return Math.log10(x) / Math.log10(2);
    }

    @Override
    public void paint(Graphics g) {
        if (curMatrix == null) {
            return;
        }
        int x, y;
        int vcell = getHeight() / ROW;
        int hcell = getWidth() / COL;

        g.setColor(Color.white);
        g.fillRect(0, 0, getWidth(), getHeight());

        /*g.setColor(Color.white);
        for (y = 0; y < ROW; y++) {
            g.drawLine(0, y * vcell, getWidth(), y * vcell);
        }
        for (x = 0; x < COL; x++) {
            g.drawLine(x * hcell, 0, x * hcell, getHeight());
        }*/
        g.setColor(Color.black);
        for (x = 0; x < COL; x++) {
            for (y = 0; y < ROW; y++) {
                if (curMatrix[x][y] == 1) { // fill
                    g.fillRect(x * hcell, y * vcell, hcell, vcell);
                }
            }
        }

        g.setColor(Color.black);
        g.drawRect(0, 0, getWidth() - 1, getHeight() - 1);

    }

    public void copyBoard(int[][] dst, int[][] src) {
//      copies all the prevMatrix values to the currBoard values
        //dst = src.clone();
        for (int x = 0; x < ROW; x++) {
            for (int y = 0; y < COL; y++) {
                int temp =  src[x][y];
                dst[x][y] =temp;
            }
        }

    }

    public void loadInit(int[][] src) {
        for (int x = 0; x < ROW; x++) {
            for (int y = 0; y < COL; y++) {
                curMatrix[x][y] = src[x][y];
                prevMatrix[x][y] = src[x][y];
            }
        }
    }

    public void printBoard() {
//      •    ->   living cell
//  a space  ->   dead cell
        for (int a = 0; a < ROW; a++) {
            for (int b = 0; b < COL; b++) {
                if (curMatrix[a][b] == 1) {
                    System.out.print("•");
                } else {
                    System.out.print("_");
                }
            }
            System.out.println("");
        }
        System.out.println("------------------------------------------------------------------------------------------------------------------------");
    }

