    public int distanciaHamming(LifeLikeCA sPrima) {
        int contador = 0;
        for (int a = 0; a < ROW; a++) {
            for (int b = 0; b < COL; b++) {
                contador += curMatrix[a][b] ^ sPrima.curMatrix[a][b];
            }
        }
        return contador;
    }

    public static double Lyapunov(int t, int et, int e0) {
        //double lyap = (1 / (double) t) * (Math.log((double) et / (double) e0)/ Math.log(2));
        double lyap = (Math.log((double) et / (double) e0) / Math.log(2));
        //System.out.println(lyap);
        return lyap;
    }

    public static void test1() {
        LifeLikeCA s = new LifeLikeCA(40, 40);
        s.random();

        System.out.println("Alive " + s.percentageAlive() + '%');
        LifeLikeCA sPrima = new LifeLikeCA();
        for (int x = 0; x < s.ROW; x++) {
            for (int y = 0; y < s.COL; y++) {
                sPrima.curMatrix[x][y] = s.curMatrix[x][y];
                sPrima.prevMatrix[x][y] = s.prevMatrix[x][y];
            }
        }
        // que sPrima tenga condiciones iniciales con distancia muy pequenha
        if (sPrima.curMatrix[0][0] == 1) {
            sPrima.curMatrix[0][0] = 0;
            sPrima.prevMatrix[0][0] = 0;
        } else {
            sPrima.curMatrix[0][0] = 1;
            sPrima.prevMatrix[0][0] = 1;
        }
        // calcular Hamming
        //System.out.println("[iter=0] " + s.distanciaHamming(sPrima));
        /// //   int e0 = s.distanciaHamming(sPrima);
        int T = 10; // infinito
        double lyap = 0.0d;
        for (int t = 1; t < T; t++) {
            // iterar
            s.step(1);
            sPrima.step(1);

            /////      int et = s.distanciaHamming(sPrima);
            // System.out.println("[t =" + t + "] " + "Lyap= " + Lyapunov(t, et, e0));
            ///     lyap += Lyapunov(t, et, e0);
        }
        lyap = (1 / (double) T) * lyap;
        System.out.println("Lyap= " + lyap);

    }

    public static void testDistancias() {
        String[] LifeGameType = {"B23/S36", "B36/S125", "B34/S34", "B357/S1358", "B345/S4567", "B378/S235678", "B3/S23", "B3/S45678", "B3678/S34678", "B35678/S5678", "B3/S012345678", "B1357/S02468", "B1/S1", "B36/S23", "B345/S5", "B3/S12345", "B3/S1234", "B368/S245", "B357/S238", "B1357/S1357", "B2/S", "B234/S", "B3678/S235678", "B45678/S2345"};
        int tam = 128;

        for (int i = 0; i < LifeGameType.length; i++) {
            System.out.print(LifeGameType[i]+";");
            LifeLikeCA s = new LifeLikeCA(tam, tam);
            s.setNewRule(LifeGameType[i]);
            s.random();           
            int T = 1000; // infinito
            int et =0;
            double value=0;
            for (int t = 0; t < T-1; t++) {
                int[][] temp = new int[tam][tam];
                //temp = s.getCurrent();
                s.copyBoard(temp,s.curMatrix );
                LifeLikeCA sPrima = new LifeLikeCA(tam, tam);
                s.setNewRule(LifeGameType[i]);
                sPrima.loadInit(temp);

                // iterar
                s.step(1);
                et = s.distanciaHamming(sPrima);
                value = (double)et/(tam*tam);
                System.out.print( value+";");
            }
            System.out.print(value);
            System.out.println();
        }


    }

